@@ -0,0 +1,8 @@
+import { readFileSync } from "fs";
+import { injectForPath } from "./inject.ts";
+
+export const readFileWithRecords = (repo: string, filePath: string): string => {
+  const content = readFileSync(filePath, "utf-8");
+  const records = injectForPath(repo, filePath);
+  return records ? records + "\n\n" + content : content;
+};
